using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.SceneManagement;using Unity.Profiling;using Unity.Profiling.LowLevel.Unsafe;using MapSharedProps;

// Isolated test Player only. Never part of the product importer or game.
public sealed class NightPlayerProbe : MonoBehaviour {
 public GameObject[] prefabs;public string[] ids,expectedShaders;public float[] sinks,heights;public int[] colliderCounts;public Camera proofCamera;public Renderer floor;
 [Serializable]public class Check {public string name,detail;public bool pass;}
 [Serializable]public class Measurement {public int placements,renderers,effects,triangles;public float dispatchMedianMs,dispatchP95Ms,completionMedianMs,completionP95Ms;public string measurement;public long drawCalls,batches,setPass,totalUsedBytes,standardDrawCalls,instancedDrawCalls,srpBatcherDrawCalls;public bool standardDrawValid,instancedDrawValid,srpBatcherDrawValid;public bool drawRecorderValid,memoryRecorderValid;public double timingCpuMs,timingGpuMs;public int timingSamples;}
 [Serializable]public class Report {public bool pass;public string error,unity,gpu,api,os,cpu,colourSpace,pipeline,configuration;public int width,height,frameStart,frameEnd,reloads;public List<Check> checks=new List<Check>();public List<Measurement> measurements=new List<Measurement>();public List<string> availableRenderCounters=new List<string>();public List<string> warnings=new List<string>(),errors=new List<string>();}
 static Report report;static int starts;readonly List<GameObject> live=new List<GameObject>();RenderTexture target;string output;bool aborted;
 static string Arg(string key,string fallback){var a=Environment.GetCommandLineArgs();int n=Array.IndexOf(a,key);return n>=0&&n+1<a.Length?a[n+1]:fallback;}
 void OnLog(string message,string stack,LogType type){if(report==null)return;if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert)report.errors.Add(message);else if(type==LogType.Warning&&report.warnings.Count<100)report.warnings.Add(message);}
 void OnDestroy(){Application.logMessageReceived-=OnLog;if(target){if(proofCamera)proofCamera.targetTexture=null;target.Release();Destroy(target);}}
 void CheckIt(string name,bool pass,string detail=""){report.checks.Add(new Check{name=name,pass=pass,detail=detail});if(!pass)throw new Exception(name+": "+detail);}
 IEnumerator Start(){output=Arg("-night-output",Path.Combine(Path.GetDirectoryName(Application.dataPath),"results"));Directory.CreateDirectory(output);Application.runInBackground=true;QualitySettings.vSyncCount=0;Application.targetFrameRate=-1;Application.logMessageReceived+=OnLog;if(report==null)report=new Report{unity=Application.unityVersion,gpu=SystemInfo.graphicsDeviceName,api=SystemInfo.graphicsDeviceType.ToString(),os=SystemInfo.operatingSystem,cpu=SystemInfo.processorType,colourSpace=QualitySettings.activeColorSpace.ToString(),pipeline=GraphicsSettings.currentRenderPipeline?GraphicsSettings.currentRenderPipeline.GetType().FullName:"none",configuration="Windows x64 Mono Development; D3D11; 1280x900 offscreen camera; vSync=0, uncapped; desktop host only",width=1280,height=900,frameStart=Time.frameCount};starts++;var run=Run();while(true){if(aborted)yield break;bool next=false;try{next=run.MoveNext();}catch(Exception e){report.error=e.ToString();Finish(1);yield break;}if(!next)yield break;if(run.Current is IEnumerator nested)yield return Guard(nested);else yield return run.Current;}}
 IEnumerator Guard(IEnumerator run){while(true){if(aborted)yield break;bool next=false;try{next=run.MoveNext();}catch(Exception e){report.error=e.ToString();Finish(1);yield break;}if(!next)yield break;if(run.Current is IEnumerator nested)yield return Guard(nested);else yield return run.Current;}}
 public void SetupTarget(){if(!target){target=new RenderTexture(1280,900,24,RenderTextureFormat.ARGB32);target.Create();proofCamera.targetTexture=target;proofCamera.aspect=1280f/900;}}
 public void Clear(){foreach(var o in live)if(o){if(Application.isPlaying)Destroy(o);else DestroyImmediate(o);}live.Clear();}
 public void Spawn(int count,bool chestsOnly=false){Clear();int columns=count<=10?5:count<=35?7:15;float spacing=chestsOnly?1.8f:4.5f;for(int k=0;k<count;k++){int i=k%(chestsOnly?7:10);var o=Instantiate(prefabs[i]);o.name=ids[i]+"-player-"+k;float sx=new[]{1f,.85f,1.15f}[k%3],sy=new[]{1f,.9f,1.1f}[k%3];o.transform.localScale=new Vector3(sx,sy,sx);o.transform.SetPositionAndRotation(new Vector3((k%columns-(columns-1)*.5f)*spacing,-sinks[i]*sy,(k/columns-(Mathf.CeilToInt(count/(float)columns)-1)*.5f)*spacing),Quaternion.Euler(0,k%3*25,0));SetTime(o,0);live.Add(o);}FrameAll();}
 public void SetTime(GameObject o,float t){foreach(var r in o.GetComponentsInChildren<Renderer>()){if(r.sharedMaterial.HasProperty("_ChestTime")){var block=new MaterialPropertyBlock();r.GetPropertyBlock(block);block.SetFloat("_ChestTime",t);r.SetPropertyBlock(block);}}var fx=o.GetComponent<ChestPresentation>();if(fx){fx.SetSeed("player-fixed-"+o.name.Split(new[]{"-player-"},StringSplitOptions.None)[0]);fx.SetTime(t);}}
 public void FrameAll(){proofCamera.orthographic=false;var rs=live.SelectMany(o=>o.GetComponentsInChildren<Renderer>()).ToArray();if(rs.Length==0)return;var bounds=rs[0].bounds;foreach(var r in rs)bounds.Encapsulate(r.bounds);float extent=Mathf.Max(bounds.size.x,bounds.size.z)+4;proofCamera.transform.position=bounds.center+new Vector3(extent*.65f,extent*.85f,-extent*.95f);proofCamera.transform.LookAt(bounds.center);floor.transform.position=new Vector3(bounds.center.x,0,bounds.center.z);floor.transform.localScale=Vector3.one*(extent+15)/10;}
 public Texture2D Capture(string name){SetupTarget();for(int i=0;i<3;i++)proofCamera.Render();var old=RenderTexture.active;RenderTexture.active=target;var image=new Texture2D(1280,900,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1280,900),0,0);image.Apply();File.WriteAllBytes(Path.Combine(output,name+".png"),image.EncodeToPNG());RenderTexture.active=old;return image;}
 public void EditorCapture(string directory){output=directory;SetupTarget();Spawn(10);var image=Capture("editor-reference-lineup");DestroyImmediate(image);Clear();proofCamera.targetTexture=null;target.Release();DestroyImmediate(target);target=null;}
 void ValidateReferences(){CheckIt("ten representative prefab references retained",prefabs.Length==10&&prefabs.All(p=>p)&&ids.Length==10);for(int i=0;i<10;i++){var p=prefabs[i];var r=p.GetComponent<Renderer>();CheckIt(ids[i]+" supported root shader retained",r&&r.sharedMaterial&&r.sharedMaterial.shader.isSupported&&r.sharedMaterial.shader.name==expectedShaders[i],r?r.sharedMaterial.shader.name:"missing");CheckIt(ids[i]+" mesh collider and scripts retained",p.GetComponent<MeshFilter>().sharedMesh.vertexCount>0&&p.GetComponentsInChildren<Collider>(true).Length==colliderCounts[i]&&p.GetComponentsInChildren<MonoBehaviour>(true).All(x=>x));if(i<7){var m=r.sharedMaterial;CheckIt(ids[i]+" surface textures and keyword retained",m.IsKeywordEnabled("CHEST_SURFACE")&&m.GetTexture("_ChestColour")?.width==512&&m.GetTexture("_ChestPacked")?.width==512&&m.GetVector("_ChestMean0").x>0);}foreach(var child in p.GetComponentsInChildren<Renderer>()){CheckIt(ids[i]+" child shader supported: "+child.name,child.sharedMaterial&&child.sharedMaterial.shader.isSupported,child.sharedMaterial.shader.name);if(child.name=="Side relief"&&i<7){var mesh=child.GetComponent<MeshFilter>().sharedMesh;var modes=new List<Vector2>();mesh.GetUVs(1,modes);bool mapped=child.sharedMaterial.IsKeywordEnabled("CHEST_SURFACE");CheckIt(ids[i]+" cast relief material and per-vertex modes survive Player",mapped&&modes.Count==mesh.vertexCount&&modes.All(v=>v.x>=0&&v.x<=3&&v.x==Mathf.Round(v.x))&&modes.Any(v=>v.x==1)&&modes.Any(v=>v.x==2)&&modes.Any(v=>v.x==3)&&child.sharedMaterial.GetTexture("_ChestPacked")?.width==512);}}}}
 ProfilerRecorder Counter(string name){var handles=new List<ProfilerRecorderHandle>();ProfilerRecorderHandle.GetAvailable(handles);foreach(var h in handles){var d=ProfilerRecorderHandle.GetDescription(h);if(d.Name.Contains("Draw")||d.Name.Contains("Batches")||d.Name.Contains("SetPass")){string text=d.Category.Name+"/"+d.Name;if(!report.availableRenderCounters.Contains(text))report.availableRenderCounters.Add(text);}if(d.Name==name)return ProfilerRecorder.StartNew(d.Category,d.Name,1);}return default;}
 IEnumerator Sample(int count){Spawn(count,true);foreach(var o in live)SetTime(o,-1);for(int k=0;k<15;k++){proofCamera.Render();yield return null;}var draw=Counter("Draw Calls Count");var batches=Counter("Batches Count");var passes=Counter("SetPass Calls Count");var standard=Counter("Standard Draw Calls Count");var instanced=Counter("Standard Instanced Draw Calls Count");var srp=Counter("SRP Batcher Draw Calls Count");var memory=ProfilerRecorder.StartNew(ProfilerCategory.Memory,"Total Used Memory",1);var dispatch=new List<float>();var complete=new List<float>();long d=0,b=0,p=0,mem=0,st=0,ins=0,sr=0;for(int k=0;k<60;k++){long begin=System.Diagnostics.Stopwatch.GetTimestamp();proofCamera.Render();dispatch.Add((float)((System.Diagnostics.Stopwatch.GetTimestamp()-begin)*1000.0/System.Diagnostics.Stopwatch.Frequency));var request=AsyncGPUReadback.Request(target,0,0,1,0,1,0,1,TextureFormat.RGBA32);long dd=0,bb=0,pp=0,ss=0,ii=0,rr=0;do{yield return null;dd=Math.Max(dd,draw.Valid?draw.LastValue:0);bb=Math.Max(bb,batches.Valid?batches.LastValue:0);pp=Math.Max(pp,passes.Valid?passes.LastValue:0);ss=Math.Max(ss,standard.Valid?standard.LastValue:0);ii=Math.Max(ii,instanced.Valid?instanced.LastValue:0);rr=Math.Max(rr,srp.Valid?srp.LastValue:0);}while(!request.done);CheckIt("GPU completed rendered sample "+count+"/"+k,!request.hasError);complete.Add((float)((System.Diagnostics.Stopwatch.GetTimestamp()-begin)*1000.0/System.Diagnostics.Stopwatch.Frequency));d+=dd;b+=bb;p+=pp;st+=ss;ins+=ii;sr+=rr;mem+=memory.Valid?memory.LastValue:0;}dispatch.Sort();complete.Sort();var rs=live.SelectMany(x=>x.GetComponentsInChildren<Renderer>()).ToArray();report.measurements.Add(new Measurement{placements=count,renderers=rs.Length,effects=live.Count(x=>x.GetComponent<ChestPresentation>()),triangles=rs.Where(r=>r.enabled).Sum(r=>r.GetComponent<MeshFilter>().sharedMesh.triangles.Length/3),dispatchMedianMs=dispatch[30],dispatchP95Ms=dispatch[57],completionMedianMs=complete[30],completionP95Ms=complete[57],measurement="Manual camera.Render CPU dispatch; completion includes 1-pixel AsyncGPUReadback and coroutine/driver wait. Neither is FPS or pure GPU frame time. 15 warm-up and 60 measured renders.",drawCalls=d/60,batches=b/60,setPass=p/60,totalUsedBytes=mem/60,drawRecorderValid=draw.Valid,memoryRecorderValid=memory.Valid,standardDrawCalls=st/60,instancedDrawCalls=ins/60,srpBatcherDrawCalls=sr/60,standardDrawValid=standard.Valid,instancedDrawValid=instanced.Valid,srpBatcherDrawValid=srp.Valid});draw.Dispose();batches.Dispose();passes.Dispose();memory.Dispose();standard.Dispose();instanced.Dispose();srp.Dispose();foreach(var o in live)SetTime(o,0);var image=Capture("player-chests-"+count);Destroy(image);}
 static int Bright(Texture2D image){return image.GetPixels32().Count(c=>c.r+c.g+c.b>35);}
 static Vector2 Centroid(Texture2D image){var px=image.GetPixels32();double x=0,y=0;int n=0;for(int k=0;k<px.Length;k++)if(px[k].r+px[k].g+px[k].b>35){x+=k%image.width;y+=k/image.width;n++;}if(n==0)throw new Exception("No visible FX pixels");return new Vector2((float)(x/n),(float)(y/n));}
 IEnumerator Effects(){Clear();yield return null;floor.enabled=false;proofCamera.backgroundColor=Color.black;proofCamera.orthographic=true;proofCamera.orthographicSize=1.6f;proofCamera.transform.position=new Vector3(1,.6f,-5);proofCamera.transform.rotation=Quaternion.identity;foreach(string id in new[]{"treasurechest_gold","treasurechest_rainbow"}){int index=Array.IndexOf(ids,id);var o=Instantiate(prefabs[index]);o.name=id+"-player-fx";o.transform.localScale=new Vector3(1.1f,.85f,1.1f);live.Add(o);var fx=o.GetComponent<ChestPresentation>();fx.SetSeed("player-position-"+id);fx.SetTime(.37f);foreach(var r in o.GetComponentsInChildren<Renderer>())r.enabled=r.sharedMaterial.shader.name=="MapSharedProps/ChestFx";yield return null;var a=Capture(id+"-fx-origin");var ca=Centroid(a);o.transform.position=Vector3.right*2;var z=Capture(id+"-fx-moved");var cb=Centroid(z);float expected=2/(proofCamera.orthographicSize*2*proofCamera.aspect)*1280;CheckIt(id+" actual FX pixels follow parent translation",Math.Abs(cb.x-ca.x-expected)<4&&Math.Abs(cb.y-ca.y)<3,"delta="+(cb-ca)+", expectedX="+expected);o.SetActive(false);yield return null;var off=Capture(id+"-fx-disabled");CheckIt(id+" disabling parent removes FX pixels",Bright(off)==0);o.SetActive(true);yield return null;var on=Capture(id+"-fx-reenabled");CheckIt(id+" enable restores fixed FX pixels",on.GetPixels32().SequenceEqual(z.GetPixels32()));fx.SetTime(1.37f);var animated=Capture(id+"-fx-time1");CheckIt(id+" FX animation survives Player shader stripping",!animated.GetPixels32().SequenceEqual(on.GetPixels32()));var owned=o.GetComponentsInChildren<Renderer>();Destroy(o);live.Clear();yield return null;yield return null;CheckIt(id+" destroyed root owns all effect renderers",owned.All(r=>!r)&&FindObjectsByType<ChestPresentation>().Length==0);var gone=Capture(id+"-fx-deleted");CheckIt(id+" deletion leaves no FX pixels",Bright(gone)==0);foreach(var image in new[]{a,z,off,on,animated,gone})Destroy(image);}floor.enabled=true;proofCamera.backgroundColor=Color.black;}
 IEnumerator Run(){SetupTarget();ValidateReferences();CheckIt("Windows Player rendering with D3D11",Application.platform==RuntimePlatform.WindowsPlayer&&SystemInfo.graphicsDeviceType==GraphicsDeviceType.Direct3D11);if(starts>1){report.reloads++;Spawn(10);for(int k=0;k<10;k++)yield return null;var re=Capture("player-scene-reload");Destroy(re);CheckIt("scene reload restores ten fixtures and two FX owners",live.Count==10&&FindObjectsByType<ChestPresentation>().Length==2);Clear();yield return null;CheckIt("runtime no errors or exceptions",report.errors.Count==0,string.Join(";",report.errors));report.pass=true;Finish(0);yield break;}Spawn(10);for(int k=0;k<20;k++)yield return null;var lineup=Capture("player-lineup");CheckIt("representative Player frame has real geometry pixels",Bright(lineup)>5000);Destroy(lineup);foreach(int i in Enumerable.Range(0,10)){Clear();yield return null;var o=Instantiate(prefabs[i]);o.name=ids[i]+"-player-close";o.transform.position=Vector3.down*sinks[i];SetTime(o,0);live.Add(o);float d=i==9?6.1f:2.2f,targetHeight=heights[i]*.42f;proofCamera.orthographic=false;proofCamera.transform.position=new Vector3(d*.6f,targetHeight+d*.35f,-d*.8f);proofCamera.transform.LookAt(new Vector3(0,targetHeight,0));var image=Capture(ids[i]+"-player-close");Destroy(image);if(i<7||ids[i]=="mausoleum"||ids[i]=="haystack"){proofCamera.transform.position=new Vector3(d*.6f,targetHeight+d*.95f,-d*.8f);proofCamera.transform.LookAt(new Vector3(0,targetHeight,0));image=Capture(ids[i]+"-player-overhead");Destroy(image);}}yield return Effects();foreach(int count in new[]{7,35,105})yield return Sample(count);Clear();yield return null;yield return null;CheckIt("all stress instances and FX removed",FindObjectsByType<ChestPresentation>().Length==0);report.frameEnd=Time.frameCount;CheckIt("Player actually advances frames",report.frameEnd-report.frameStart>180,"frames="+(report.frameEnd-report.frameStart));File.WriteAllText(Path.Combine(output,"before-reload.json"),JsonUtility.ToJson(report,true));SceneManager.LoadScene(0);}
 void Finish(int code){if(code!=0)aborted=true;report.pass=code==0&&report.pass&&string.IsNullOrEmpty(report.error)&&report.checks.All(c=>c.pass);File.WriteAllText(Path.Combine(output,"player-report.json"),JsonUtility.ToJson(report,true));Application.Quit(code);}
}
